function t(key, vars) {
  const dict = i18n[currentLang] || i18n.ar;
  let str = dict[key] ?? i18n.en[key] ?? i18n.ar[key] ?? key;
  if (vars) Object.keys(vars).forEach(k => { str = str.replace(`{${k}}`, vars[k]); });
  if (typeof RTL_LANGS !== 'undefined' && !RTL_LANGS.includes(currentLang) && /[←→]/.test(str)) {
    str = str.replace(/←/g, '@@ARROW@@').replace(/→/g, '←').replace(/@@ARROW@@/g, '→');
  }
  return str;
}
